const app=document.querySelector('#app');
const {levels,generate,advance}=GardenMath;
function read(key){try{const n=Number(localStorage.getItem(key));return Number.isFinite(n)?Math.max(0,Math.floor(n)):0;}catch{return 0;}}
function save(key,value){try{localStorage.setItem(key,String(value));}catch{}}
let stars=read('garden-stars'),savedLevel=Math.min(levels.length-1,read('garden-level'));
let selected=savedLevel,round=0,earned=0,independent=0,assisted=false,locked=false,current;
let timerId=null,startedAt=null,elapsed=0;
function formatTime(ms){const sec=Math.floor(ms/1000);return `${String(Math.floor(sec/60)).padStart(2,'0')}:${String(sec%60).padStart(2,'0')}`;}
function updateTimer(){if(startedAt!==null)elapsed=Math.max(0,Date.now()-startedAt);const el=document.querySelector('#timer');if(el)el.textContent=`Time ${formatTime(elapsed)}`;}
function stopTimer(){if(timerId!==null){updateTimer();clearInterval(timerId);timerId=null;}startedAt=null;}
function gradeFor(score){return ['D','C','B','B+','A','A+'][Math.max(0,Math.min(5,score))];}
function renderEquation(q){if(q.kind==='three')return `<div class="vertical-equation" role="math" aria-label="${q.a} plus ${q.b} minus ${q.c} equals what?"><div class="vertical-row"><span></span><span>${q.a}</span></div><div class="vertical-row"><span>+</span><span>${q.b}</span></div><div class="vertical-row"><span>&minus;</span><span>${q.c}</span></div><div class="vertical-result">?</div></div>`;if(['tens','carry','borrow'].includes(q.kind))return `<div class="vertical-equation" role="math" aria-label="${q.a} ${q.op==='+'?'plus':'minus'} ${q.b} equals what?"><div class="vertical-row"><span></span><span>${q.a}</span></div><div class="vertical-row"><span>${q.op}</span><span>${q.b}</span></div><div class="vertical-result">?</div></div>`;return `<div class="equation">${q.equation}</div>`;}
function updateStars(){document.querySelector('#stars').textContent=stars;save('garden-stars',stars);}
function home(){
stopTimer();updateStars();app.innerHTML=`<section class="hero"><div><div class="eyebrow">Small steps. Bigger discoveries.</div><h1>Grow your<br><em>math magic.</em></h1><p>Start with little sums. Grow into two-digit numbers solve the mystery of x, and learn your times tables!</p><span class="pill">A practice timer and a grade for every round.</span></div><div class="garden" aria-label="A sunny flower garden"><span class="sun">☀</span><div class="plants">🌷 🌻 🌱</div><span class="garden-note">A little harder. A little stronger.</span></div></section><section class="table-study"><h2>Learn your multiplication tables</h2><label for="study-table">Choose a table </label><select id="study-table">${Array.from({length:12},(_,i)=>`<option value="${i+1}">${i+1} times table</option>`).join('')}</select><div id="table-facts" class="table-facts"></div><button class="primary" id="practice-table">Practice this table ?</button></section><div class="section-head"><div><h2>Your math adventure</h2><p>Get 4 out of 5 right without help to move up a level.</p></div></div><section class="progress-panel"><span class="icon">🌱</span><div class="grow"><strong>Continue at level ${savedLevel+1}: ${levels[savedLevel].title}</strong><p>Your level saves on this browser. You can also pick any level below.</p><button class="primary" id="continue">Continue adventure →</button></div></section><div class="level-grid">${levels.filter(l=>l.kind!=='multiply').map((l,i)=>`<button class="level-card ${i===savedLevel?'current-level':''}" data-level="${i}"><span class="level-number">${i+1}</span><div><h3>${l.title}</h3><p>${l.description}</p><span class="go">${i<savedLevel?'Practice again':'Let’s try'} →</span></div></button>`).join('')}</div><p class="save-note">★ ${stars} stars collected · A star for every question you work through.</p>`;
const tableSelect=document.querySelector('#study-table');tableSelect.onchange=()=>showTable(Number(tableSelect.value));showTable(1);document.querySelector('#practice-table').onclick=()=>start(7+Number(tableSelect.value));
document.querySelector('#continue').onclick=()=>start(savedLevel);document.querySelectorAll('[data-level]').forEach(el=>el.onclick=()=>start(Number(el.dataset.level)));
}
function showTable(table){document.querySelector('#table-facts').innerHTML=Array.from({length:12},(_,i)=>`<div>${table} &times; ${i+1} = <strong>${table*(i+1)}</strong></div>`).join('');}
function start(index){stopTimer();selected=index;round=0;earned=0;independent=0;startedAt=Date.now();elapsed=0;question();timerId=setInterval(updateTimer,250);}
function question(){locked=false;assisted=false;current=generate(selected);app.innerHTML=`<div class="practice"><div class="topline"><button class="quiet" id="back">← Garden</button><span>Level ${selected+1} · ${round+1} of 5</span><span class="timer" id="timer" role="timer" aria-label="Round time">Time ${formatTime(elapsed)}</span></div><div class="track"><div class="fill" style="width:${round*20}%"></div></div><section class="exercise"><div class="eyebrow">${levels[selected].title}</div>${current.kind==='missing'?'<p>x is a mystery number. Find its value!</p>':''}${renderEquation(current)}<div class="answers">${current.choices.map(n=>`<button class="answer" data-value="${n}">${current.kind==='missing'?'x = ':''}${n}</button>`).join('')}</div><div class="feedback" role="status" aria-live="polite" id="feedback">${current.kind==='missing'?'What number is hiding behind x?':'Choose your answer.'}</div><button class="quiet" id="hintbutton">☀ A little help, please</button><div id="hint"></div><button class="primary" id="next" hidden>Next question →</button></section></div>`;
document.querySelector('#back').onclick=home;document.querySelectorAll('[data-value]').forEach(el=>el.onclick=()=>check(el));document.querySelector('#hintbutton').onclick=hint;updateTimer();document.querySelector('#next').onclick=()=>{round++;round===5?finish():question();};}
function hint(){assisted=true;document.querySelector('#hint').innerHTML=`<div class="hint">${current.help}</div>`;}
function check(el){if(locked||el.disabled)return;if(Number(el.dataset.value)!==current.answer){assisted=true;el.classList.add('wrong');el.disabled=true;document.querySelector('#feedback').textContent='Good try! Let’s work it out together.';hint();return;}locked=true;earned++;if(round===4)stopTimer();stars++;if(!assisted)independent++;updateStars();el.classList.add('correct');document.querySelectorAll('.answer').forEach(btn=>btn.disabled=true);document.querySelector('#feedback').textContent='★ You did it! Your math skills are growing.';document.querySelector('#hintbutton').hidden=true;document.querySelector('#next').hidden=false;document.querySelector('#next').textContent=round===4?'See how you grew →':'Next question →';}
function finish(){stopTimer();const grade=gradeFor(independent);const next=advance(selected,independent),promoted=next>selected,mastered=independent>=4&&selected===levels.length-1;savedLevel=Math.max(savedLevel,next);save('garden-level',savedLevel);app.innerHTML=`<section class="finish"><div class="big">${promoted||mastered?'🌻':'🌱'}</div><div class="eyebrow">Level ${selected+1} complete</div><h1>${promoted?'Ready to grow!':mastered?'Math superstar!':'Keep growing!'}</h1><div class="grade-badge" aria-label="Grade ${grade}">${grade}</div><p>You earned ${earned} stars and solved ${independent} of 5 questions without help.</p><p class="result-time">Round time: <strong>${formatTime(elapsed)}</strong></p><p class="grade-key">Grades use first-try answers without hints.<br>5/5: A+ | 4/5: A | 3/5: B+ | 2/5: B | 1/5: C | 0/5: D<br>Time is for practice and does not change your grade.</p><p>${promoted?`Next: level ${next+1}, ${levels[next].title}.`:mastered?'You reached the top level! Keep practicing with new challenges.':'Let’s practice this level again. Solve 4 without help to move up.'}</p><button class="primary" id="again">${promoted?'Try the next level →':'Practice with new questions →'}</button><br><button class="quiet" id="done">Back to my garden</button></section>`;document.querySelector('#again').onclick=()=>start(next);document.querySelector('#done').onclick=home;}
document.querySelector('#home').onclick=e=>{e.preventDefault();home();};home();
